text:
問題点は `var i` が関数スコープの単一変数であり、5つのコールバックが同じ `i` を共有していることです。ループ終了後に `i` は `5` になるため、すべて `console.log(5)` になります。

修正版：

```js
for (let i = 0; i < 5; i++) {
  setTimeout(() => console.log(i), 100);
}
```

`let` は各反復ごとに新しい `i` を作るため、出力は `0 1 2 3 4` になります。

`var` を使う場合の代替例：

```js
for (var i = 0; i < 5; i++) {
  setTimeout((j) => console.log(j), 100, i);
}
```

```go
package main

import (
	"context"
	"io"
	"net/http"
	"sync"
	"time"
)

// URLResult は各 URL の取得結果を表す
type URLResult struct {
	URL        string
	StatusCode int
	Body       []byte
	Err        error
}

// FetchAllURLs は複数の URL を並行して取得し、全体を 10 秒でタイムアウトする
func FetchAllURLs(ctx context.Context, urls []string) []URLResult {
	// 10 秒の全体タイムアウトを設定する
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()

	results := make([]URLResult, len(urls))
	var wg sync.WaitGroup

	// 各 URL を並行して取得する
	for i, url := range urls {
		wg.Add(1)
		go func(i int, url string) {
			defer wg.Done()

			req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
			if err != nil {
				results[i] = URLResult{URL: url, Err: err}
				return
			}

			resp, err := http.DefaultClient.Do(req)
			if err != nil {
				results[i] = URLResult{URL: url, Err: err}
				return
			}
			// レスポンスボディは必ず閉じる
			defer resp.Body.Close()

			body, err := io.ReadAll(resp.Body)
			if err != nil {
				results[i] = URLResult{URL: url, StatusCode: resp.StatusCode, Err: err}
				return
			}

			results[i] = URLResult{
				URL:        url,
				StatusCode: resp.StatusCode,
				Body:       body,
			}
		}(i, url)
	}

	// すべての URL の取得が終わるまで待つ
	wg.Wait()
	return results
}
```
